  const command_id=eventCommand(run.id,s.id,source),old=await c.query('SELECT receipt FROM ow_dungeon_awards WHERE instance=$1 AND character=$2 AND source=$3',[run.id,s.id,source]);if(old.rowCount)return old.rows[0].receipt as Receipt;
  if(run.privateRules.stageKeys&&run.definition.numericStage){run.keyProgress??={};run.keyProgress[s.id]=stageKeyProgress(s,run.definition.numericStage,run.definition.id,run.definition.worldTierScaling?run.worldTier:0,run.privateRules.stageKeys.pool);}
  recordTaskCompletions(s,before,new Date().toISOString());s.revision++;await c.query('UPDATE ow_characters SET state=$1 WHERE id=$2',[s,s.id]);const receipt:Receipt={command_id,revision:s.revision,delta,rewards,snapshot:await this.ctx.snapshot(c,s)};
