 private async saveLocation(c:PoolClient,s:CharacterState,run:SavedRun,pending:boolean,source:string){(s as any).dungeon={instance:pending?null:run.id,pendingResult:pending?run.id:null,returnRegion:run.definition.policy.returnRegion};await this.changeCharacter(c,s,run,source,{gold:0,xp:0,material:0});}
 private async assertFree(c:PoolClient,s:CharacterState){if((s as any).dungeon?.pendingResult)this.ctx.fail('DUNGEON_RESULT','请先返回营地处理上一场结果。');if((await c.query('SELECT 1 FROM ow_dungeon_members WHERE character=$1 AND active',[s.id])).rowCount)this.ctx.fail('DUNGEON_ACTIVE','角色已经参与另一场副本。');}
